import { expect, test } from '../fixtures';

// Starts from the bob session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_BOB! });

test('Details save', async ({ page }) => {
  await test.step('Open the user details', async () => {
    await page.goto('/user/settings/user-details');
  });

  await test.step('Type a location', async () => {
    await page.getByRole('textbox', { name: 'Location', exact: true }).fill('Lucknow');
  });

  await test.step('Press Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The success message is shown [code]', async () => {
    await expect(page.locator('.alert-success')).toContainText('User details updated.');
  });

  await test.step('The saved location is shown in the field [code]', async () => {
    await expect(page.getByRole('textbox', { name: 'Location', exact: true })).toHaveValue('Lucknow');
  });
});
